355:     jsi::Runtime& runtime,
356:     HighResTimeStamp taskEndTime) {
357:   TraceSection s("RuntimeScheduler::updateRendering");
358: 
359:   // This is the integration of the Event Timing API in the Event Loop.
360:   // See https://w3c.github.io/event-timing/#sec-modifications-HTML
361:   const auto eventTimingDelegate = eventTimingDelegate_.load();
362:   if (eventTimingDelegate != nullptr) {
363:     eventTimingDelegate->dispatchPendingEventTimingEntries(
364:         taskEndTime, surfaceIdsWithPendingRenderingUpdates_);
365:   }
366: 
367:   // This is the integration of the Resize Observer API in the Event Loop. See
368:   // https://w3c.github.io/csswg-drafts/resize-observer/#broadcast-resize-notifications-h
369:   // The delegate runs the spec's depth-bounded gather/broadcast loop
370:   // internally; this call site stays a single invocation per tick.
371:   if (resizeObserverDelegate_ != nullptr) {
372:     // This delivers the observations to JS synchronously, so it is outside the
373:     // error boundary of `executeTask`. Report the error without going through
374:     // `handleTaskError`: we are already inside the "update the rendering" step,
375:     // so clearing the queues here would drop the pending rendering updates this
376:     // step is about to drain, and a throwing observer callback would abort the
377:     // remaining steps below.
378:     try {
379:       resizeObserverDelegate_->runResizeObservations(runtime);
380:     } catch (jsi::JSError& error) {
381:       onTaskError_(runtime, error);
382:     } catch (std::exception& ex) {
383:       jsi::JSError error(
384:           runtime, std::string("Non-JS exception: ") + ex.what());
385:       onTaskError_(runtime, error);
386:     }
387:   }
388: 
389:   // This is the integration of the Intersection Observer API in the Event Loop.
390:   // See
391:   if (intersectionObserverDelegate_ != nullptr) {
392:     intersectionObserverDelegate_->updateIntersectionObservations(
393:         surfaceIdsWithPendingRenderingUpdates_);
394:   }
395: 
396:   surfaceIdsWithPendingRenderingUpdates_.clear();
397: 
398:   while (!pendingRenderingUpdates_.empty()) {
399:     auto& pendingRenderingUpdate = pendingRenderingUpdates_.front();
400:     if (pendingRenderingUpdate != nullptr) {
401:       pendingRenderingUpdate();
402:     }
403:     pendingRenderingUpdates_.pop();
404:   }
405: }

