295: std::shared_ptr<Task> RuntimeScheduler_Modern::selectTask() {
296:   // We need a unique lock here because we'll also remove executed tasks from
297:   // the top of the queue.
298:   std::unique_lock lock(schedulingMutex_);
299: 
300:   // It's safe to reset the flag here, as its access is also synchronized with
301:   // the access to the task queue.
302:   isEventLoopScheduled_ = false;
303: 
304:   // Skip executed tasks
305:   while (!taskQueue_.empty() && !taskQueue_.top()->callback) {
306:     taskQueue_.pop();
307:   }
308: 
309:   if (!taskQueue_.empty()) {
310:     return taskQueue_.top();
311:   }
312: 
313:   return nullptr;
