43: static inline HighResDuration timeoutForSchedulerPriority(SchedulerPriority schedulerPriority) noexcept
44: {
45:   switch (schedulerPriority) {
46:     case SchedulerPriority::ImmediatePriority:
47:       return HighResDuration::fromChrono(std::chrono::milliseconds(0));
48:     case SchedulerPriority::UserBlockingPriority:
49:       return HighResDuration::fromChrono(std::chrono::milliseconds(250));
50:     case SchedulerPriority::NormalPriority:
51:       return HighResDuration::fromChrono(std::chrono::seconds(5));
52:     case SchedulerPriority::LowPriority:
53:       return HighResDuration::fromChrono(std::chrono::seconds(10));
54:     case SchedulerPriority::IdlePriority:
55:       return HighResDuration::fromChrono(std::chrono::minutes(5));
56:     default:
57:       react_native_assert(false && "Unsupported SchedulerPriority value");
58:       return HighResDuration::fromChrono(std::chrono::seconds(5));
59:   }
60: }

