150: struct TraceSection {
151:  public:
152:   template <typename... ConvertsToStringPiece>
153:   explicit TraceSection(const char *name, ConvertsToStringPiece &&...args) : systraceSectionUnwrapped_(name, args...)
154:   {
155:     os_log_t instrumentsLogHandle = systrace::getOrCreateInstrumentsLogHandle();
156: 
157:     // If the log isn't enabled, we don't want the performance overhead of the
158:     // rest of the code below.
159:     if (!os_signpost_enabled(instrumentsLogHandle)) {
160:       return;
161:     }
162: 
163:     name_ = name;
164: 
165:     const auto argsVector = std::vector<std::string>{systrace::render(args)...};
166:     std::string argsString = "";
167:     for (size_t i = 0; i < argsVector.size(); i += 2) {
168:       argsString += argsVector[i] + "=" + argsVector[i + 1] + ";";
169:     }
170: 
171:     signpostID_ = os_signpost_id_make_with_pointer(instrumentsLogHandle, this);
172: 
173:     os_signpost_interval_begin(instrumentsLogHandle, signpostID_, "Systrace", "%s begin: %s", name, argsString.c_str());
174:   }
175: 
176:   ~TraceSection()
177:   {
178:     // We don't need to gate on os_signpost_enabled here because it's already
179:     // checked in os_signpost_interval_end.
180:     os_signpost_interval_end(systrace::instrumentsLogHandle, signpostID_, "Systrace", "%s end", name_.data());
181:   }
182: 
183:  private:
184:   os_signpost_id_t signpostID_ = OS_SIGNPOST_ID_INVALID;
185:   std::string_view name_;
186:   TraceSectionUnwrapped systraceSectionUnwrapped_;
187: };

