133:   // Sort frames by beginTimestamp to handle out-of-order arrivals caused by
134:   // async screenshot encoding. The initial synthetic frame may arrive in the
135:   // buffer after real frames because its screenshot encoding takes longer than
136:   // one vsync (~16ms). Sorting ensures the idle-gap detection loop below sees
137:   // frames in chronological order.
138:   std::sort(
139:       frameTimings.begin(),
140:       frameTimings.end(),
141:       [](const FrameTimingSequence& a, const FrameTimingSequence& b) {
142:         return a.beginTimestamp < b.beginTimestamp;
143:       });
144: 
145:   // Compute the next available sequence ID for synthetic frames (idle frames
146:   // and dropped frames).
147:   FrameSequenceId nextSyntheticSeqId = 0;
148:   for (const auto& ft : frameTimings) {
149:     nextSyntheticSeqId = std::max(nextSyntheticSeqId, ft.id + 1);
150:   }
151: 
152:   std::optional<HighResTimeStamp> prevEndTimestamp;
153: 
154:   for (auto&& frameTimingSequence : frameTimings) {
155:     // Serialize all events for this frame.
156:     folly::dynamic frameEvents = folly::dynamic::array();
157:     size_t totalFrameBytes = 0;
158: 
159:     // Detect idle period: gap between previous frame's end and this frame's
160:     // begin exceeding one vsync interval. Emit NeedsBeginFrameChanged +
161:     // BeginFrame to fill the gap. Chrome DevTools renders a BeginFrame
162:     // without a corresponding DrawFrame as an "Idle frame".
163:     auto minIdleGap =
164:         frameTimingSequence.vsyncInterval > HighResDuration::zero()
165:         ? frameTimingSequence.vsyncInterval
166:         : DEFAULT_VSYNC_INTERVAL;
167:     if (prevEndTimestamp.has_value() &&
168:         (frameTimingSequence.beginTimestamp - *prevEndTimestamp) > minIdleGap) {
169:       auto needsBeginFrameEvent =
170:           TraceEventGenerator::createNeedsBeginFrameChangedEvent(
171:               FALLBACK_LAYER_TREE_ID,
172:               *prevEndTimestamp,
173:               processId,
174:               frameTimingSequence.threadId);
175:       auto serializedNeedsBeginFrame =
176:           TraceEventSerializer::serialize(std::move(needsBeginFrameEvent));
177:       totalFrameBytes +=
178:           TraceEventSerializer::estimateJsonSize(serializedNeedsBeginFrame);
179:       frameEvents.push_back(std::move(serializedNeedsBeginFrame));
180: 
181:       auto idleBeginEvent = TraceEventGenerator::createIdleBeginFrameEvent(
182:           nextSyntheticSeqId++,
183:           FALLBACK_LAYER_TREE_ID,
184:           *prevEndTimestamp,
185:           processId,
186:           frameTimingSequence.threadId);
187: 
188:       auto serializedIdleBegin =
189:           TraceEventSerializer::serialize(std::move(idleBeginEvent));
190:       totalFrameBytes +=
191:           TraceEventSerializer::estimateJsonSize(serializedIdleBegin);
