400: void consoleTimeStamp(
401:     jsi::Runtime& runtime,
402:     const jsi::Value* arguments,
403:     size_t argumentsCount) {
404:   auto& performanceTracer = tracing::PerformanceTracer::getInstance();
405:   if ((!performanceTracer.isTracing() && !ReactPerfettoLogger::isTracing()) ||
406:       argumentsCount == 0) {
407:     // If not tracing, just early return to avoid the cost of parsing.
408:     return;
409:   }
410: 
411:   const jsi::Value& labelArgument = arguments[0];
412:   std::string label;
413:   if (labelArgument.isString()) {
414:     label = labelArgument.asString(runtime).utf8(runtime);
415:   } else {
416:     auto maybeStringifiedLabel = stringifyJsiValue(labelArgument, runtime);
417:     if (maybeStringifiedLabel) {
418:       label = std::move(*maybeStringifiedLabel);
419:     } else {
420:       // Do not record this entry: unable to reliably stringify the label.
421:       return;
422:     }
423:   }
424: 
425:   auto now = HighResTimeStamp::now();
426:   std::optional<tracing::ConsoleTimeStampEntry> start;
427:   if (argumentsCount >= 2) {
428:     const jsi::Value& startArgument = arguments[1];
429:     if (startArgument.isNumber()) {
430:       start =
431:           HighResTimeStamp::fromDOMHighResTimeStamp(startArgument.asNumber());
432:     } else if (startArgument.isString()) {
433:       start = startArgument.asString(runtime).utf8(runtime);
434:     } else if (startArgument.isUndefined()) {
435:       start = now;
436:     }
437:   }
438: 
439:   std::optional<tracing::ConsoleTimeStampEntry> end;
440:   if (argumentsCount >= 3) {
441:     const jsi::Value& endArgument = arguments[2];
442:     if (endArgument.isNumber()) {
443:       end = HighResTimeStamp::fromDOMHighResTimeStamp(endArgument.asNumber());
444:     } else if (endArgument.isString()) {
445:       end = endArgument.asString(runtime).utf8(runtime);
446:     } else if (endArgument.isUndefined()) {
447:       end = now;
448:     }
449:   }
450: 
451:   std::optional<std::string> trackName;
452:   std::optional<std::string> trackGroup;
453:   std::optional<tracing::ConsoleTimeStampColor> color;
454:   if (argumentsCount >= 4) {
455:     const jsi::Value& trackNameArgument = arguments[3];
456:     if (trackNameArgument.isString()) {
457:       trackName = trackNameArgument.asString(runtime).utf8(runtime);
458:     }
459:   }
460:   if (argumentsCount >= 5) {
461:     const jsi::Value& trackGroupArgument = arguments[4];
462:     if (trackGroupArgument.isString()) {
463:       trackGroup = trackGroupArgument.asString(runtime).utf8(runtime);
464:     }
465:   }
466:   if (argumentsCount >= 6) {
467:     const jsi::Value& colorArgument = arguments[5];
468:     if (colorArgument.isString()) {
469:       color = tracing::getConsoleTimeStampColorFromString(
470:           colorArgument.asString(runtime).utf8(runtime));
471:     }
472:   }
473: 
474:   std::optional<folly::dynamic> detail;
475:   if (performanceTracer.isTracing() && argumentsCount >= 7) {
476:     const jsi::Value& detailArgument = arguments[6];
477:     if (detailArgument.isObject()) {
478:       detail =
479:           tracing::getConsoleTimeStampDetailFromObject(runtime, detailArgument);
480:     }
481:   }
482: 
483:   if (performanceTracer.isTracing()) {
484:     auto taskContext = ConsoleTaskOrchestrator::getInstance().top();
485: 
486:     performanceTracer.reportTimeStamp(
487:         label,
488:         start,
489:         end,
490:         trackName,
491:         trackGroup,
492:         color,
493:         std::move(detail),
494:         taskContext ? taskContext->getSerializedStackTrace() : nullptr);
495:   }
496: 
497:   if (ReactPerfettoLogger::isTracing()) {
498:     std::optional<HighResTimeStamp> perfettoStart =
499:         getTimeStampForPerfetto(start, now);
500:     std::optional<HighResTimeStamp> perfettoEnd =
501:         getTimeStampForPerfetto(end, now);
502: 
503:     if (perfettoStart && perfettoEnd) {
504:       ReactPerfettoLogger::measure(
505:           label, *perfettoStart, *perfettoEnd, trackName, trackGroup);
506:     }
507:   }
508: }

