166:       } else {
167:         handleUpdate();
168:       }
169:       addPendingLog = null;
170:     };
171: 
172:     const optimisticTimeout = setTimeout(() => {
173:       if (addPendingLog) {
174:         addPendingLog();
175:       }
176:     }, OPTIMISTIC_WAIT_TIME);
177: 
178:     newLog.symbolicate(status => {
179:       if (addPendingLog && status !== 'PENDING') {
180:         addPendingLog();
181:         clearTimeout(optimisticTimeout);
182:       } else if (status !== 'PENDING') {
183:         // The log has already been added but we need to trigger a render.
184:         handleUpdate();
185:       }
186:     });

587: - (void)_handleJSError:(const JsErrorHandler::ProcessedError &)error withRuntime:(jsi::Runtime &)runtime
588: {
589:   NSMutableDictionary<NSString *, id> *errorData = [NSMutableDictionary new];
590:   errorData[@"message"] = @(error.message.c_str());
591:   if (error.originalMessage) {
592:     errorData[@"originalMessage"] = @(error.originalMessage->c_str());
593:   }
594:   if (error.name) {
595:     errorData[@"name"] = @(error.name->c_str());
596:   }
597:   if (error.componentStack) {
598:     errorData[@"componentStack"] = @(error.componentStack->c_str());
599:   }
600: 
601:   NSMutableArray<NSDictionary<NSString *, id> *> *stack = [NSMutableArray new];
602:   for (const JsErrorHandler::ProcessedError::StackFrame &frame : error.stack) {
603:     NSMutableDictionary<NSString *, id> *stackFrame = [NSMutableDictionary new];
604:     if (frame.file) {
605:       stackFrame[@"file"] = @(frame.file->c_str());
606:     }
607:     stackFrame[@"methodName"] = @(frame.methodName.c_str());
608:     if (frame.lineNumber) {
609:       stackFrame[@"lineNumber"] = @(*frame.lineNumber);
610:     }
611:     if (frame.column) {
612:       stackFrame[@"column"] = @(*frame.column);
613:     }
614:     [stack addObject:stackFrame];
615:   }
616: 
617:   errorData[@"stack"] = stack;
618:   errorData[@"id"] = @(error.id);
619:   errorData[@"isFatal"] = @(error.isFatal);
620: 
621:   id extraData =
622:       TurboModuleConvertUtils::convertJSIValueToObjCObject(runtime, jsi::Value(runtime, error.extraData), nullptr);
623:   if (extraData) {
624:     errorData[@"extraData"] = extraData;
625:   }
626: 
627:   if (![_delegate instance:self
628:           didReceiveJSErrorStack:errorData[@"stack"]
629:                          message:errorData[@"message"]
630:                  originalMessage:errorData[@"originalMessage"]
631:                             name:errorData[@"name"]
632:                   componentStack:errorData[@"componentStack"]
633:                      exceptionId:error.id
634:                          isFatal:[errorData[@"isFatal"] boolValue]
635:                        extraData:errorData[@"extraData"]]) {
636:     JS::NativeExceptionsManager::ExceptionData jsErrorData{errorData};
637:     id<NativeExceptionsManagerSpec> exceptionsManager = [_turboModuleManager moduleForName:"ExceptionsManager"];
638:     [exceptionsManager reportException:jsErrorData];
639:   }
640: }

