221: - (void)showErrorMessage:(NSString *)message
222:                withStack:(NSArray<RCTJSStackFrame *> *)stack
223:                 isUpdate:(BOOL)isUpdate
224:              errorCookie:(int)errorCookie
225: {
226:   // Remove ANSI color codes from the message
227:   NSString *messageWithoutAnsi = [self stripAnsi:message];
228: 
229:   BOOL isRootViewControllerPresented = self.presentingViewController != nil;
230:   // Show if this is a new message, or if we're updating the previous message
231:   BOOL isNew = !isRootViewControllerPresented && !isUpdate;
232:   BOOL isUpdateForSameMessage = !isNew &&
233:       (isRootViewControllerPresented && isUpdate &&
234:        ((errorCookie == -1 && [_lastErrorMessage isEqualToString:messageWithoutAnsi]) ||
235:         (errorCookie == _lastErrorCookie)));
236:   if (isNew || isUpdateForSameMessage) {
237:     _lastStackTrace = stack;
238:     // message is displayed using UILabel, which is unable to render text of
239:     // unlimited length, so we truncate it
240:     _lastErrorMessage = [messageWithoutAnsi substringToIndex:MIN((NSUInteger)10000, messageWithoutAnsi.length)];
241:     _lastErrorCookie = errorCookie;
242: 
243:     [_stackTraceTableView reloadData];
244: 
245:     if (!isRootViewControllerPresented) {
246:       [_stackTraceTableView scrollToRowAtIndexPath:[NSIndexPath indexPathForRow:0 inSection:0]
247:                                   atScrollPosition:UITableViewScrollPositionTop
248:                                           animated:NO];
249:       [RCTKeyWindow().rootViewController presentViewController:self animated:YES completion:nil];
250:     }
251:   }
252: }

