252: void _RCTLogNativeInternal(RCTLogLevel level, const char *fileName, int lineNumber, NSString *format, ...)
253: {
254:   RCTLogFunction logFunction = RCTGetLocalLogFunction();
255:   BOOL log = RCT_DEBUG || (logFunction != nil);
256:   if (log && level >= RCTGetLogThreshold()) {
257:     // Get message
258:     va_list args;
259:     va_start(args, format);
260:     NSString *message = [[NSString alloc] initWithFormat:format arguments:args];
261:     va_end(args);
262: 
263:     // Call log function
264:     if (logFunction) {
265:       logFunction(
266:           level, RCTLogSourceNative, fileName ? @(fileName) : nil, lineNumber > 0 ? @(lineNumber) : nil, message);
267:     }
268: 
269:     // Log to red box if one is configured.
270:     if (RCTSharedApplication() && RCTRedBoxGetEnabled() && level >= RCTLOG_REDBOX_LEVEL) {
271:       NSArray<NSString *> *stackSymbols = [NSThread callStackSymbols];
272:       NSMutableArray<NSDictionary *> *stack = [NSMutableArray arrayWithCapacity:(stackSymbols.count - 1)];
273:       [stackSymbols enumerateObjectsUsingBlock:^(NSString *frameSymbols, NSUInteger idx, __unused BOOL *stop) {
274:         if (idx == 0) {
275:           // don't include the current frame
276:           return;
277:         }
278: 
279:         NSRange range = NSMakeRange(0, frameSymbols.length);
280:         NSTextCheckingResult *match = [nativeStackFrameRegex() firstMatchInString:frameSymbols options:0 range:range];
281:         if (!match) {
282:           return;
283:         }
284: 
285:         NSString *methodName = [frameSymbols substringWithRange:[match rangeAtIndex:1]];
286:         char *demangledName = abi::__cxa_demangle([methodName UTF8String], NULL, NULL, NULL);
287:         if (demangledName) {
288:           methodName = @(demangledName);
289:           free(demangledName);
290:         }
291: 
292:         if (idx == 1 && fileName) {
293:           NSString *file = [@(fileName) componentsSeparatedByString:@"/"].lastObject;
294:           [stack addObject:@{@"methodName" : methodName, @"file" : file, @"lineNumber" : @(lineNumber)}];
295:         } else {
296:           [stack addObject:@{@"methodName" : methodName}];
297:         }
298:       }];
299: 
300:       dispatch_async(dispatch_get_main_queue(), ^{
301:         // red box is thread safe, but by deferring to main queue we avoid a startup
302:         // race condition that causes the module to be accessed before it has loaded
303:         RCTModuleRegistry *moduleRegistry = RCTLogBridgeModuleRegistry ?: RCTLogBridgelessModuleRegistry;
304:         id redbox = [moduleRegistry moduleForName:"RedBox" lazilyLoadIfNecessary:YES];
305:         if (redbox) {
306:           void (*showErrorMessage)(id, SEL, NSString *, NSMutableArray<NSDictionary *> *) =
307:               (__typeof__(showErrorMessage))objc_msgSend;
308:           SEL showErrorMessageSEL = NSSelectorFromString(@"showErrorMessage:withStack:");
309: 
310:           if ([redbox respondsToSelector:showErrorMessageSEL]) {
311:             showErrorMessage(redbox, showErrorMessageSEL, message, stack);
312:           }
313:         }
314:       });
315:     }
316: 
317: #if RCT_DEBUG
318:     if (!RCTRunningInTestEnvironment()) {
319:       // Log to JS executor
320:       NSString *levelString = level ? @(RCTLogLevels[level]) : @"info";
321:       RCTCallableJSModules *callableModule = RCTLogBridgeCallableJSModules ?: RCTLogBridgelessCallableJSModules;
322:       [callableModule invokeModule:@"RCTLog" method:@"logIfNoNativeHook" withArgs:@[ levelString, message ]];
323:     }
324: #endif
325:   }
326: }

