652: void ReactInstance::handleMemoryPressureJs(int pressureLevel) {
653:   // The level is an enum value passed by the Android OS to an onTrimMemory
654:   // event callback. Defined in ComponentCallbacks2.
655:   enum AndroidMemoryPressure {
656:     TRIM_MEMORY_BACKGROUND = 40,
657:     TRIM_MEMORY_COMPLETE = 80,
658:     TRIM_MEMORY_MODERATE = 60,
659:     TRIM_MEMORY_RUNNING_CRITICAL = 15,
660:     TRIM_MEMORY_RUNNING_LOW = 10,
661:     TRIM_MEMORY_RUNNING_MODERATE = 5,
662:     TRIM_MEMORY_UI_HIDDEN = 20,
663:   };
664:   const char* levelName = nullptr;
665:   switch (pressureLevel) {
666:     case TRIM_MEMORY_BACKGROUND:
667:       levelName = "TRIM_MEMORY_BACKGROUND";
668:       break;
669:     case TRIM_MEMORY_COMPLETE:
670:       levelName = "TRIM_MEMORY_COMPLETE";
671:       break;
672:     case TRIM_MEMORY_MODERATE:
673:       levelName = "TRIM_MEMORY_MODERATE";
674:       break;
675:     case TRIM_MEMORY_RUNNING_CRITICAL:
676:       levelName = "TRIM_MEMORY_RUNNING_CRITICAL";
677:       break;
678:     case TRIM_MEMORY_RUNNING_LOW:
679:       levelName = "TRIM_MEMORY_RUNNING_LOW";
680:       break;
681:     case TRIM_MEMORY_RUNNING_MODERATE:
682:       levelName = "TRIM_MEMORY_RUNNING_MODERATE";
683:       break;
684:     case TRIM_MEMORY_UI_HIDDEN:
685:       levelName = "TRIM_MEMORY_UI_HIDDEN";
686:       break;
687:     default:
688:       levelName = "UNKNOWN";
689:       break;
690:   }
691: 
692:   switch (pressureLevel) {
693:     case TRIM_MEMORY_RUNNING_LOW:
694:     case TRIM_MEMORY_RUNNING_MODERATE:
695:     case TRIM_MEMORY_UI_HIDDEN:
696:       // For non-severe memory trims, do nothing.
697:       LOG(INFO) << "Memory warning (pressure level: " << levelName
698:                 << ") received by JS VM, ignoring because it's non-severe";
699:       break;
700:     case TRIM_MEMORY_BACKGROUND:
701:     case TRIM_MEMORY_COMPLETE:
702:     case TRIM_MEMORY_MODERATE:
703:     case TRIM_MEMORY_RUNNING_CRITICAL:
704:       // For now, pressureLevel is unused by collectGarbage.
705:       // This may change in the future if the JS GC has different styles of
706:       // collections.
707:       LOG(INFO) << "Memory warning (pressure level: " << levelName
708:                 << ") received by JS VM, running a GC";
709:       runtimeScheduler_->scheduleWork([=](jsi::Runtime& runtime) {
710:         TraceSection s("ReactInstance::handleMemoryPressure");
711:         runtime.instrumentation().collectGarbage(levelName);
712:       });
713:       break;
714:     default:
715:       // Use the raw number instead of the name here since the name is
716:       // meaningless.
717:       LOG(WARNING) << "Memory warning (pressure level: " << pressureLevel
718:                    << ") received by JS VM, unrecognized pressure level";
719:       break;
720:   }
721: }

