293: void JSIExecutor::handleMemoryPressure(int pressureLevel) {
294:   // The level is an enum value passed by the Android OS to an onTrimMemory
295:   // event callback. Defined in ComponentCallbacks2.
296:   enum AndroidMemoryPressure {
297:     TRIM_MEMORY_BACKGROUND = 40,
298:     TRIM_MEMORY_COMPLETE = 80,
299:     TRIM_MEMORY_MODERATE = 60,
300:     TRIM_MEMORY_RUNNING_CRITICAL = 15,
301:     TRIM_MEMORY_RUNNING_LOW = 10,
302:     TRIM_MEMORY_RUNNING_MODERATE = 5,
303:     TRIM_MEMORY_UI_HIDDEN = 20,
304:   };
305:   const char* levelName;
306:   switch (pressureLevel) {
307:     case TRIM_MEMORY_BACKGROUND:
308:       levelName = "TRIM_MEMORY_BACKGROUND";
309:       break;
310:     case TRIM_MEMORY_COMPLETE:
311:       levelName = "TRIM_MEMORY_COMPLETE";
312:       break;
313:     case TRIM_MEMORY_MODERATE:
314:       levelName = "TRIM_MEMORY_MODERATE";
315:       break;
316:     case TRIM_MEMORY_RUNNING_CRITICAL:
317:       levelName = "TRIM_MEMORY_RUNNING_CRITICAL";
318:       break;
319:     case TRIM_MEMORY_RUNNING_LOW:
320:       levelName = "TRIM_MEMORY_RUNNING_LOW";
321:       break;
322:     case TRIM_MEMORY_RUNNING_MODERATE:
323:       levelName = "TRIM_MEMORY_RUNNING_MODERATE";
324:       break;
325:     case TRIM_MEMORY_UI_HIDDEN:
326:       levelName = "TRIM_MEMORY_UI_HIDDEN";
327:       break;
328:     default:
329:       levelName = "UNKNOWN";
330:       break;
331:   }
332: 
333:   switch (pressureLevel) {
334:     case TRIM_MEMORY_RUNNING_LOW:
335:     case TRIM_MEMORY_RUNNING_MODERATE:
336:     case TRIM_MEMORY_UI_HIDDEN:
337:       // For non-severe memory trims, do nothing.
338:       LOG(INFO) << "Memory warning (pressure level: " << levelName
339:                 << ") received by JS VM, ignoring because it's non-severe";
340:       break;
341:     case TRIM_MEMORY_BACKGROUND:
342:     case TRIM_MEMORY_COMPLETE:
343:     case TRIM_MEMORY_MODERATE:
344:     case TRIM_MEMORY_RUNNING_CRITICAL:
345:       // For now, pressureLevel is unused by collectGarbage.
346:       // This may change in the future if the JS GC has different styles of
347:       // collections.
348:       LOG(INFO) << "Memory warning (pressure level: " << levelName
349:                 << ") received by JS VM, running a GC";
350:       runtime_->instrumentation().collectGarbage(levelName);
351:       break;
352:     default:
353:       // Use the raw number instead of the name here since the name is
354:       // meaningless.
355:       LOG(WARNING) << "Memory warning (pressure level: " << pressureLevel
356:                    << ") received by JS VM, unrecognized pressure level";
357:       break;
358:   }
359: }

