96: export function computeWindowedRenderLimits(
97:   props: CellMetricProps,
98:   maxToRenderPerBatch: number,
99:   windowSize: number,
100:   prev: {
101:     first: number,
102:     last: number,
103:   },
104:   listMetrics: ListMetricsAggregator,
105:   scrollMetrics: {
106:     dt: number,
107:     offset: number,
108:     velocity: number,
109:     visibleLength: number,
110:     zoomScale: number,
111:     ...
112:   },
113: ): {
114:   first: number,
115:   last: number,
116: } {
117:   const itemCount = props.getItemCount(props.data);
118:   if (itemCount === 0) {
119:     return {first: 0, last: -1};
120:   }
121:   const {offset, velocity, visibleLength, zoomScale = 1} = scrollMetrics;
122: 
123:   // Start with visible area, then compute maximum overscan region by expanding from there, biased
124:   // in the direction of scroll. Total overscan area is capped, which should cap memory consumption
125:   // too.
126:   const visibleBegin = Math.max(0, offset);
127:   const visibleEnd = visibleBegin + visibleLength;
128:   const overscanLength = (windowSize - 1) * visibleLength;
129: 
130:   // Considering velocity seems to introduce more churn than it's worth.
131:   const leadFactor = 0.5; // Math.max(0, Math.min(1, velocity / 25 + 0.5));
132: 
133:   const fillPreference =
134:     velocity > 1 ? 'after' : velocity < -1 ? 'before' : 'none';
135: 
136:   const overscanBegin = Math.max(
137:     0,
138:     visibleBegin - (1 - leadFactor) * overscanLength,
139:   );
140:   const overscanEnd = Math.max(0, visibleEnd + leadFactor * overscanLength);
141: 
142:   const lastItemOffset =
143:     listMetrics.getCellMetricsApprox(itemCount - 1, props).offset * zoomScale;
144:   if (lastItemOffset < overscanBegin) {
145:     // Entire list is before our overscan window
146:     return {
147:       first: Math.max(0, itemCount - 1 - maxToRenderPerBatch),
148:       last: itemCount - 1,
149:     };
150:   }
151: 
152:   // Find the indices that correspond to the items at the render boundaries we're targeting.
153:   let [overscanFirst, first, last, overscanLast] = elementsThatOverlapOffsets(
154:     [overscanBegin, visibleBegin, visibleEnd, overscanEnd],
155:     props,
156:     listMetrics,
157:     zoomScale,
158:   );
159:   overscanFirst = overscanFirst == null ? 0 : overscanFirst;
160:   first = first == null ? Math.max(0, overscanFirst) : first;
161:   overscanLast = overscanLast == null ? itemCount - 1 : overscanLast;
162:   last =
163:     last == null
164:       ? Math.min(overscanLast, first + maxToRenderPerBatch - 1)
165:       : last;
166:   const visible = {first, last};
167: 
168:   // We want to limit the number of new cells we're rendering per batch so that we can fill the
169:   // content on the screen quickly. If we rendered the entire overscan window at once, the user
170:   // could be staring at white space for a long time waiting for a bunch of offscreen content to
171:   // render.
172:   let newCellCount = newRangeCount(prev, visible);
173: 
174:   while (true) {
175:     if (first <= overscanFirst && last >= overscanLast) {
176:       // If we fill the entire overscan range, we're done.
177:       break;
178:     }
179:     const maxNewCells = newCellCount >= maxToRenderPerBatch;
180: 
181:     let firstWillAddMore;
182:     let lastWillAddMore;
183: 
184:     if (ReactNativeFeatureFlags.fixVirtualizeListCollapseWindowSize()) {
185:       firstWillAddMore = first <= prev.first;
186:       lastWillAddMore = last >= prev.last;
187:     } else {
188:       firstWillAddMore = first <= prev.first || first > prev.last;
189:       lastWillAddMore = last >= prev.last || last < prev.first;
190:     }
191: 
192:     const firstShouldIncrement =
193:       first > overscanFirst && (!maxNewCells || !firstWillAddMore);
194:     const lastShouldIncrement =
195:       last < overscanLast && (!maxNewCells || !lastWillAddMore);
196:     if (maxNewCells && !firstShouldIncrement && !lastShouldIncrement) {
197:       // We only want to stop if we've hit maxNewCells AND we cannot increment first or last
198:       // without rendering new items. This let's us preserve as many already rendered items as
199:       // possible, reducing render churn and keeping the rendered overscan range as large as
200:       // possible.
201:       break;
202:     }
203:     if (
204:       firstShouldIncrement &&
205:       !(fillPreference === 'after' && lastShouldIncrement && lastWillAddMore)
206:     ) {
207:       if (firstWillAddMore) {
208:         newCellCount++;
209:       }
210:       first--;
211:     }
212:     if (
213:       lastShouldIncrement &&
214:       !(fillPreference === 'before' && firstShouldIncrement && firstWillAddMore)
215:     ) {
216:       if (lastWillAddMore) {
217:         newCellCount++;
218:       }
219:       last++;
220:     }
221:   }
222:   if (!(
223:     last >= first &&
224:     first >= 0 &&
225:     last < itemCount &&
226:     first >= overscanFirst &&
227:     last <= overscanLast &&
228:     first <= visible.first &&
229:     last >= visible.last
230:   )) {
231:     throw new Error(
232:       'Bad window calculation ' +
233:         JSON.stringify({
234:           first,
235:           last,
236:           itemCount,
237:           overscanFirst,
238:           overscanLast,
239:           visible,
240:         }),
241:     );
242:   }
243:   return {first, last};
244: }

