484:   RCTPerformanceLogger *performanceLogger = [_bridge performanceLogger];
485:   NSArray<NSNumber *> *values = [performanceLogger valuesForTags];
486:   for (NSString *label in LabelsForRCTPerformanceLoggerTags()) {
487:     long long value = values[i + 1].longLongValue - values[i].longLongValue;
